// Firmware tunables that are NOT part of the mechanism contract.
// Mechanism values live in include/mechanism.h (generated by the lead's sim).
#pragma once
#include <stdint.h>

namespace dc {

// Pololu #5229 exact gearbox ratio (same expression as the motor component test).
constexpr double kGearRatio =
    (25.0 * 34 * 35 * 34 * 34 * 34 * 27) / (12.0 * 9 * 12 * 14 * 14 * 14 * 9);
constexpr double kCountsPerRev = 12.0 * kGearRatio;  // ~11836.88 quadrature counts/output rev
constexpr float kCountsPerDeg = static_cast<float>(kCountsPerRev / 360.0);

// ASSUMPTION: ~35 rpm output at 12 V, 100 % duty, no load. Used only as the
// velocity feed-forward; the position/velocity feedback absorbs the error.
constexpr float kNoLoadRpm = 35.0f;

inline constexpr float rpmToCountsPerMs(float rpm) {
  return static_cast<float>(rpm * kCountsPerRev / 60000.0);
}
inline int32_t degToCounts(float deg) {
  const float c = deg * kCountsPerDeg;
  return static_cast<int32_t>(c >= 0 ? c + 0.5f : c - 0.5f);
}

namespace cfg {
// Motion control (duty is -1..1).
constexpr uint32_t kControlPeriodMs = 5;
constexpr float kVelFilterAlpha = 0.35f;   // IIR on encoder speed estimate
constexpr float kKp = 0.004f;              // duty per count of position error
constexpr float kKv = 0.08f;               // duty per count/ms of velocity error
constexpr float kPosTolDeg = 1.0f;         // move "done" tolerance
constexpr float kFinalTolDeg = 4.0f;       // worst error accepted after timeout
constexpr uint32_t kMoveExtraMs = 800;     // time allowed past the profile end
constexpr float kWrongDirDeg = 4.0f;       // moving this far the wrong way = encoder/motor polarity fault
constexpr uint32_t kBrakeMs = 120;         // short-brake hold after every move

// Homing: seek the home-switch press edge moving forward.
constexpr float kHomeRpm = 8.0f;
constexpr float kHomeMaxDeg = 450.0f;      // > 1 rev: switch must be found within this
constexpr uint32_t kSwitchDebounceMs = 4;  // home switch
constexpr uint32_t kButtonDebounceMs = 30; // Select / Back

// Load cell (HX711 at 10 SPS): samples averaged for baseline / after-drop.
constexpr uint8_t kScaleSamples = 4;
constexpr uint32_t kScaleTimeoutMs = 1500;

// Pickup / reminders.
constexpr uint32_t kPickupRemindMs = 60000UL;            // first reminder after 1 min
constexpr uint32_t kReminderPeriodMs = 30000UL;          // beep burst every 30 s
constexpr uint32_t kReminderGiveUpMs = 30UL * 60000UL;   // then log "not taken"
constexpr uint32_t kFaultBeepMs = 60000UL;               // fault beeps for 1 min

// UI and schedule.
constexpr uint32_t kBootSettleMs = 300;
constexpr uint32_t kMenuTimeoutMs = 30000UL;
constexpr uint32_t kDoseGraceS = 30UL * 60UL;  // late (e.g. after power loss) doses still given within 30 min
constexpr int kDoseStepMin = 15;               // dose time editing resolution
constexpr int kAdcMax = 4095;
}  // namespace cfg
}  // namespace dc
